<?php
$event_date = '';
$event_time = '';
$options = RT\Core\Common\Options::getOption();
$lang = get_locale() === 'vi' ? 'vi' : 'en';
$general_title = $options['event_general_title_' . $lang];
$general_form = $options['event_general_form_' . $lang];
$is_form_overdue = false;
$form_output = null;
$event_register_show = !empty($data['event_register_show']) ? $data['event_register_show'] : false;
$regist_title = !empty($data['event_register_title']) ? $data['event_register_title'] : (!empty($general_title) ? $general_title : '');
$regist_form = !empty($data['event_register_form']) ? $data['event_register_form'] : (!empty($general_form) ? $general_form : '');

// Date
if (!empty($data['event_date_start'])) {
    $event_date .= date('d.m.Y', strtotime($data['event_date_start']));

    if (strtotime($data['event_date_start']) <= strtotime(date('Ymd'))) {
        $is_form_overdue = true;
    } else {
        $form_output = do_shortcode('[wpforms id="' . $regist_form . '"]');
    }
}

if (!empty($data['event_date_end']) && !empty($data['event_date_start']) && strtotime($data['event_date_start']) != strtotime($data['event_date_end'])) {
    $event_date .= (!empty($event_date) ? ' - ' : '') . date(' d.m.Y', strtotime($data['event_date_end']));
}

// Time
if (!empty($data['event_time_start'])) {
    $event_time .= $data['event_time_start'];
}

if (!empty($data['event_time_end'])) {
    $event_time .= (!empty($event_time) ? ' - ' : '') . $data['event_time_end'];
}
?>
<?php if (!empty($regist_title) && !empty($regist_form) && $event_register_show && !$is_form_overdue) : ?>
