            if (!empty($data['event_image_mobile']['url'])) {
                $banner_mobile = $data['event_image_mobile']['url'];
            }
            ?>
            <div class="rt-event__information__image rt-img-drop">
                <picture class="lazy">
                    <data-src srcset="<?= $data['event_image_desktop']['url']; ?>" media="(min-width: 992px)"></data-src>
